package org.telegram.ui;
import android.content.Context;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import androidx.recyclerview.widget.*;
import java.util.*;
import org.telegram.ui.Components.ClaudMusicStyle;
import org.telegram.messenger.*;
import org.telegram.messenger.music.*;
import org.telegram.ui.ActionBar.*;

/** Recycled, cursor-paginated SoundCloud playlists, artist profiles and claud collections. */
public final class ClaudSoundCloudBrowseActivity extends BaseFragment {
 private final String mode,arg,label;private RecyclerView list;private Adapter adapter;private TextView status,more,profile,follow,profileArt,profileName;private String next;private boolean loading,started,artistPlaylists,saving;private int generation,offset;private SoundCloudPublic.Playlist playlist;private SoundCloudPublic.Artist artist;
 private final ArrayList<Row> rows=new ArrayList<>();private final ArrayList<SoundCloudPublic.Track> tracks=new ArrayList<>();private final HashSet<String> seen=new HashSet<>(),cursors=new HashSet<>();
 public ClaudSoundCloudBrowseActivity(String mode,String arg,String label){this.mode=mode;this.arg=arg;this.label=label;}
 private int dp(float n){return AndroidUtilities.dp(n);}private TextView text(Context c,String value,int size){TextView t=new TextView(c);t.setText(value);t.setTextSize(size);t.setTextColor(0xFFF7EDE4);return t;}
 private GradientDrawable bg(int color){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(16));return g;}
 private TextView button(LinearLayout parent,String name,Runnable click){TextView t=text(parent.getContext(),name,15);t.setPadding(dp(16),dp(13),dp(16),dp(13));t.setGravity(Gravity.CENTER);t.setTextColor(0xFFF5F1ED);t.setBackground(ClaudMusicStyle.touch(0xFF252220,24));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,dp(46));bp.setMargins(0,dp(6),dp(8),dp(6));parent.addView(t,bp);t.setOnClickListener(v->click.run());return t;}
 @Override public View createView(Context c){actionBar.setTitle(label);actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setBackgroundColor(ClaudMusicStyle.BG);actionBar.setTitleColor(0xFFF7EDE4);actionBar.setItemsColor(0xFFF1B08B,false);actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){public void onItemClick(int id){if(id==-1)finishFragment();}});LinearLayout root=new LinearLayout(c);root.setOrientation(1);root.setPadding(dp(18),dp(8),dp(18),dp(8));root.setBackgroundColor(ClaudMusicStyle.BG);
  if(mode.equals("artist")){profileArt=ClaudMusicStyle.cover(c,50,null);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(96),dp(96));ap.gravity=Gravity.CENTER_HORIZONTAL;ap.setMargins(0,dp(16),0,dp(16));root.addView(profileArt,ap);profileName=ClaudMusicStyle.text(c,label,27,true,ClaudMusicStyle.TEXT);profileName.setGravity(Gravity.CENTER);root.addView(profileName);profile=text(c,"Загрузка…",14);profile.setTextColor(0xFFB9A79E);profile.setMaxLines(4);profile.setGravity(Gravity.CENTER);profile.setPadding(dp(12),dp(10),dp(12),dp(10));root.addView(profile);profile.setOnClickListener(v->profile.setMaxLines(profile.getMaxLines()==4?100:4));follow=button(root,"",()->{if(artist!=null){SoundCloudLibrary.follow(currentAccount,artist);updateFollow();}});LinearLayout.LayoutParams followLp=(LinearLayout.LayoutParams)follow.getLayoutParams();followLp.gravity=Gravity.CENTER_HORIZONTAL;follow.setLayoutParams(followLp);follow.setEnabled(false);LinearLayout tabs=new LinearLayout(c);root.addView(tabs);button(tabs,"Треки",()->{artistPlaylists=false;reset();load();});button(tabs,"Плейлисты",()->{artistPlaylists=true;reset();load();});loadArtist();}
  if(mode.equals("public")){profileArt=ClaudMusicStyle.cover(c,16,null);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(154),dp(154));ap.gravity=Gravity.CENTER_HORIZONTAL;ap.setMargins(0,dp(14),0,dp(16));root.addView(profileArt,ap);LinearLayout publicActions=new LinearLayout(c);publicActions.setGravity(Gravity.CENTER);root.addView(publicActions);button(publicActions,"Воспроизвести",()->publicPlaylist(true));button(publicActions,"Сохранить",()->publicPlaylist(false));}
  if(mode.equals("library")){button(root,"＋ Создать плейлист",()->SoundCloudCollectionActions.create(this,this::local));button(root,"Поиск",()->presentFragment(new ClaudSoundCloudActivity("")));}
  status=text(c,"",13);status.setTextColor(0xFFB7A69B);status.setPadding(0,dp(8),0,dp(8));root.addView(status);list=new RecyclerView(c);list.setLayoutManager(new LinearLayoutManager(c));adapter=new Adapter();list.setAdapter(adapter);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.addOnScrollListener(new RecyclerView.OnScrollListener(){public void onScrolled(RecyclerView r,int dx,int dy){if(dy>0&&((LinearLayoutManager)r.getLayoutManager()).findLastVisibleItemPosition()>=rows.size()-5)load();}});more=text(c,"",14);more.setTextColor(0xFFF1B08B);more.setGravity(Gravity.CENTER);more.setPadding(0,dp(14),0,dp(14));root.addView(more);more.setOnClickListener(v->load());fragmentView=root;
  if(mode.equals("library")||mode.equals("local"))local();else load();return root;
 }
 private void publicPlaylist(boolean play){if(saving||getParentActivity()==null)return;saving=true;status.setText(play?"Готовлю очередь плейлиста…":"Сохраняю все доступные треки плейлиста…");int request=generation;new Thread(()->{try{SoundCloudPublic.Playlist p=SoundCloudPublic.playlist(arg);ArrayList<SoundCloudPublic.Track> all=new ArrayList<>();HashSet<String> ids=new HashSet<>();for(int i=0;i<SoundCloudPublic.playlistSize(p);i+=50){if(request!=generation)return;for(SoundCloudPublic.Track t:SoundCloudPublic.playlistTracks(p,i))if(ids.add(t.id))all.add(t);}AndroidUtilities.runOnUIThread(()->{if(request!=generation||list==null)return;saving=false;if(play){if(all.isEmpty()){status.setText("Нет доступных для воспроизведения треков");return;}SoundCloudPlayback.play(getParentActivity(),all,all.get(0));presentFragment(new ClaudSoundCloudPlayerActivity());status.setText("В очереди: "+all.size()+" треков");}else{SoundCloudLibrary.importPlaylist(currentAccount,p.title,all);status.setText("Сохранено в коллекцию: "+all.size()+" треков");}});}catch(Exception e){AndroidUtilities.runOnUIThread(()->{if(request!=generation||list==null)return;saving=false;status.setText("Не удалось сохранить плейлист. Проверь VPN и повтори.");});}},"claud-sc-save-playlist").start();}
 private void updateFollow(){if(follow!=null&&artist!=null){follow.setEnabled(true);follow.setText(SoundCloudLibrary.following(currentAccount,artist.id)?"Отписаться":"Подписаться");}}
 private void loadArtist(){int request=generation;new Thread(()->{try{SoundCloudPublic.Artist a=SoundCloudPublic.artist(arg);AndroidUtilities.runOnUIThread(()->{if(profile==null)return;artist=a;profileName.setText(a.name);profile.setText(a.followers+" подписчиков · SoundCloud"+(a.description.isEmpty()?"":"\n"+a.description));SoundCloudArtwork.bind(profileArt,ClaudMusicStyle.large(a.avatar));updateFollow();});}catch(Exception e){AndroidUtilities.runOnUIThread(()->{if(profile!=null){profile.setText("Не удалось загрузить профиль.");}});}},"claud-sc-artist").start();}
 private void reset(){++generation;loading=false;started=false;next=null;offset=0;rows.clear();tracks.clear();seen.clear();saving=false;cursors.clear();if(adapter!=null)adapter.notifyDataSetChanged();}
 private void local(){if(list==null)return;reset();if(mode.equals("library")){for(Map.Entry<String,String> e:SoundCloudLibrary.playlists(currentAccount).entrySet()){String id=e.getKey(),name=e.getValue();int count=SoundCloudLibrary.tracks(currentAccount,id).size();ArrayList<SoundCloudPublic.Track> saved=SoundCloudLibrary.tracks(currentAccount,id);rows.add(new Row(name,count+" треков",saved.isEmpty()?"":saved.get(0).artwork,()->presentFragment(new ClaudSoundCloudBrowseActivity("local",id,name)),null));}for(SoundCloudPublic.Artist a:SoundCloudLibrary.following(currentAccount))rows.add(new Row(a.name,"Артист",a.avatar,()->presentFragment(new ClaudSoundCloudBrowseActivity("artist",a.id,a.name)),null));status.setText("Плейлисты и подписки");}else{tracks.addAll(SoundCloudLibrary.tracks(currentAccount,arg));for(SoundCloudPublic.Track t:tracks)addTrackRow(t);status.setText(tracks.size()+" треков");}more.setText("");more.setEnabled(false);adapter.notifyDataSetChanged();}
 private void addTrackRow(SoundCloudPublic.Track t){rows.add(new Row(t.title,t.artist+" · SoundCloud",t.artwork,()->{SoundCloudPlayback.play(getParentActivity(),new ArrayList<>(tracks),t);presentFragment(new ClaudSoundCloudPlayerActivity());},()->{if(mode.equals("local"))new AlertDialog.Builder(getParentActivity()).setTitle(t.title).setItems(new String[]{"Добавить в другой плейлист","Убрать из этого плейлиста","Профиль автора"},(d,w)->{if(w==0)SoundCloudCollectionActions.add(this,t);else if(w==1){SoundCloudLibrary.remove(currentAccount,arg,t.id);local();}else{SoundCloudPublic.Artist a=SoundCloudPublic.artistFor(t);if(a!=null)presentFragment(new ClaudSoundCloudBrowseActivity("artist",a.id,a.name));}}).show();else SoundCloudCollectionActions.track(this,t);}));}
 private void load(){if(list==null||loading||mode.equals("library")||mode.equals("local")||(started&&next==null))return;String selectedPath="/users/"+arg+(artistPlaylists?"/playlists_without_albums":"/tracks");String cursor=next;if(cursor!=null&&cursors.contains(cursor)){next=null;more.setText("Конец выдачи");return;}int request=generation;int startOffset=offset;loading=true;more.setEnabled(false);more.setText("Загрузка…");status.setText(rows.isEmpty()?"Загрузка из SoundCloud…":""+rows.size());new Thread(()->{try{SoundCloudPublic.CatalogPage page=null;ArrayList<SoundCloudPublic.Track> songs=null;SoundCloudPublic.Playlist loaded=playlist;String following;int newOffset=startOffset;
  if(mode.equals("public")){if(loaded==null)loaded=SoundCloudPublic.playlist(arg);songs=SoundCloudPublic.playlistTracks(loaded,startOffset);newOffset=startOffset+50;following=newOffset<SoundCloudPublic.playlistSize(loaded)?String.valueOf(newOffset):null;}else{page=SoundCloudPublic.catalog(selectedPath,"",cursor);following=page.next;}
  SoundCloudPublic.CatalogPage result=page;ArrayList<SoundCloudPublic.Track> resultSongs=songs;SoundCloudPublic.Playlist resultPlaylist=loaded;int resultOffset=newOffset;String resultNext=following;
  AndroidUtilities.runOnUIThread(()->{if(request!=generation||list==null)return;loading=false;started=true;if(cursor!=null)cursors.add(cursor);next=resultNext;offset=resultOffset;playlist=resultPlaylist;if(profileArt!=null&&mode.equals("public")&&playlist!=null&&profileArt.getTag()==null)SoundCloudArtwork.bind(profileArt,ClaudMusicStyle.large(playlist.artwork));int first=rows.size();if(resultSongs!=null)for(SoundCloudPublic.Track t:resultSongs)if(seen.add("t"+t.id)){tracks.add(t);addTrackRow(t);}if(result!=null){for(SoundCloudPublic.Track t:result.tracks)if(seen.add("t"+t.id)){tracks.add(t);addTrackRow(t);}for(SoundCloudPublic.Playlist p:result.playlists)if(seen.add("p"+p.id))rows.add(new Row(p.title,p.owner+" · "+p.count+" треков",p.artwork,()->presentFragment(new ClaudSoundCloudBrowseActivity("public",p.id,p.title)),null));for(SoundCloudPublic.Artist a:result.artists)if(seen.add("a"+a.id))rows.add(new Row(a.name,a.followers+" подписчиков · SoundCloud",a.avatar,()->presentFragment(new ClaudSoundCloudBrowseActivity("artist",a.id,a.name)),null));}int added=rows.size()-first;if(added>0)adapter.notifyItemRangeInserted(first,added);status.setText(rows.isEmpty()?"Доступных результатов нет":""+rows.size()+" · SoundCloud");more.setEnabled(next!=null);more.setText(next==null?"Конец списка":"Загрузить ещё");if(next!=null&&(!list.canScrollVertically(1)||added==0))list.post(this::load);});
 }catch(Exception e){AndroidUtilities.runOnUIThread(()->{if(request!=generation||list==null)return;loading=false;status.setText("Не удалось загрузить. Проверь соединение.");more.setEnabled(true);more.setText("Повторить");});}},"claud-sc-catalog").start();}
 private static final class Row{final String title,sub,art;final Runnable click,hold;Row(String title,String sub,String art,Runnable click,Runnable hold){this.title=title;this.sub=sub;this.art=art;this.click=click;this.hold=hold;}}
 private final class Holder extends RecyclerView.ViewHolder{TextView art,title,sub;Holder(LinearLayout v,TextView a,TextView t,TextView s){super(v);art=a;title=t;sub=s;}}
 private final class Adapter extends RecyclerView.Adapter<Holder>{public int getItemCount(){return rows.size();}public Holder onCreateViewHolder(ViewGroup parent,int type){Context c=parent.getContext();LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));row.setLayoutParams(new RecyclerView.LayoutParams(-1,dp(82)));TextView art=text(c,"♪",26);art.setGravity(Gravity.CENTER);row.addView(art,new LinearLayout.LayoutParams(dp(62),dp(62)));LinearLayout labels=new LinearLayout(c);labels.setOrientation(1);labels.setPadding(dp(14),0,0,0);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));TextView title=text(c,"",16),sub=text(c,"",12);title.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));title.setMaxLines(2);sub.setPadding(0,dp(5),0,0);sub.setTextColor(0xFFB9A69B);sub.setMaxLines(1);labels.addView(title);labels.addView(sub);return new Holder(row,art,title,sub);}public void onBindViewHolder(Holder h,int pos){Row row=rows.get(pos);h.title.setText(row.title);h.sub.setText(row.sub);h.art.setTag(null);h.art.setText("");h.art.setBackground(new ClaudMusicStyle.Cover());ClaudMusicStyle.round(h.art,row.sub.equals("Артист")?40:10);SoundCloudArtwork.bind(h.art,ClaudMusicStyle.large(row.art));h.itemView.setOnClickListener(v->row.click.run());h.itemView.setOnLongClickListener(row.hold==null?null:v->{row.hold.run();return true;});}public void onViewRecycled(Holder h){h.art.setTag(null);}}
 @Override public void onResume(){super.onResume();if(mode.equals("library")||mode.equals("local"))local();updateFollow();}
 @Override public void onFragmentDestroy(){++generation;list=null;profile=null;follow=null;profileArt=null;profileName=null;super.onFragmentDestroy();}
}
